import { t } from '../i18n';
import { TopBar, useAsync } from '../ui/kit';

interface Credit {
  name: string;
  what: string;
  license: string;
  url: string;
}

/** Sources and licences: generated by the data pipeline into data/credits.json. */
export function About() {
  const credits = useAsync<Credit[]>(
    () =>
      fetch(`${import.meta.env.BASE_URL}data/credits.json`).then((r) => (r.ok ? (r.json() as Promise<Credit[]>) : [])),
    [],
  );
  return (
    <div class="shell">
      <TopBar title={t('about.title')} backTo="settings" />
      <main class="page no-nav">
        <section class="card col">
          <h2>{t('app.name')}</h2>
          <p>{t('about.body')}</p>
          <p class="small muted">{t('about.faNotice')}</p>
        </section>
        <h2>{t('about.sources')}</h2>
        <div class="list">
          {(credits.data ?? []).map((c) => (
            <div key={c.name} style={{ display: 'block' }}>
              <b dir="ltr">{c.name}</b>
              <div class="small muted" dir="auto">
                {c.what}
              </div>
              <div class="tiny muted" dir="ltr">
                {c.license} · {c.url}
              </div>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}
